"use server";

import { revalidatePath } from "next/cache";
import { db } from "@/lib/db";
import { requireRoleForAction } from "@/lib/auth/guard";
import { writeAuditLog } from "@/lib/audit/log";

/**
 * Invoice actions — Admin + Staff, matching Quote's access level (an
 * Invoice only ever exists because a Quote it belongs to was Approved).
 * No create action here: an Invoice is only ever generated by
 * `updateQuoteAction` (src/actions/quotes.ts) the moment a Quote reaches
 * `APPROVED` — never by a form, per the "automatically generated" request.
 * No edit action on Invoice or InvoiceItem either — see the InvoiceItem
 * model comment in schema.prisma for why that's not an oversight.
 *
 * `markInvoicePaidAction` is deliberately one-directional for this first
 * pass (no "mark unpaid" to undo it) — the developer asked for the
 * generation function first and said fine-tuning (refunds, partial
 * payments, undo) comes later; see docs/OPEN_DECISIONS.md.
 */

export async function markInvoicePaidAction(invoiceId: string): Promise<void> {
  const actor = await requireRoleForAction(["ADMIN", "STAFF"]);

  const existing = await db.invoice.findUnique({ where: { id: invoiceId } });
  if (!existing) throw new Error("Invoice not found.");
  if (existing.status === "PAID") return; // already paid — no-op, not an error

  await db.$transaction(async (tx) => {
    await tx.invoice.update({
      where: { id: invoiceId },
      data: { status: "PAID", paidAt: new Date() },
    });
    await writeAuditLog(
      {
        actorUserId: actor.id,
        action: "INVOICE_PAID",
        targetType: "Invoice",
        targetId: invoiceId,
      },
      tx,
    );
  });

  revalidatePath("/invoices");
  revalidatePath(`/invoices/${invoiceId}`);
}
